import\('./db.js'\).then\(async \({ query }\) => {
  // Secuencias
  const q7 = await query\(\\`
    SELECT sequence_name, data_type, start_value, minimum_value, maximum_value, increment, cycle_option
    FROM information_schema.sequences
    WHERE sequence_schema = 'public'
    ORDER BY sequence_name
  \\`\);
  console.log\('=== SEQUENCES ==='\);
  console.log\(JSON.stringify\(q7.rows, null, 2\)\);

  // FKs detalladas
  const q8 = await query\(\\`
    SELECT
      tc.table_name AS tabla_origen,
      kcu.column_name AS columna_origen,
      ccu.table_name AS tabla_destino,
      ccu.column_name AS columna_destino,
      tc.constraint_name,
      rc.update_rule,
      rc.delete_rule
    FROM information_schema.table_constraints tc
    JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema
    JOIN information_schema.constraint_column_usage ccu ON ccu.constraint_name = tc.constraint_name AND ccu.table_schema = tc.table_schema
    JOIN information_schema.referential_constraints rc ON rc.constraint_name = tc.constraint_name AND rc.constraint_schema = tc.table_schema
    WHERE tc.table_schema = 'public' AND tc.constraint_type = 'FOREIGN KEY'
    ORDER BY tc.table_name, tc.constraint_name
  \\`\);
  console.log\('=== FOREIGN KEYS ==='\);
  console.log\(JSON.stringify\(q8.rows, null, 2\)\);

  // Triggers
  const q9 = await query\(\\`
    SELECT trigger_name, event_manipulation, event_object_table, action_timing, action_statement
    FROM information_schema.triggers
    WHERE trigger_schema = 'public'
    ORDER BY event_object_table, trigger_name
  \\`\);
  console.log\('=== TRIGGERS ==='\);
  console.log\(JSON.stringify\(q9.rows, null, 2\)\);

  // Tablas tmp_
  const q10 = await query\(\\`
    SELECT table_name FROM information_schema.tables
    WHERE table_schema = 'public' AND table_type = 'BASE TABLE' AND table_name LIKE 'tmp%'
    ORDER BY table_name
  \\`\);
  console.log\('=== TABLAS TMP ==='\);
  console.log\(JSON.stringify\(q10.rows, null, 2\)\);
}\).catch\(e => console.error\(e\)\);
" 2>&1)

